('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Phishing ist eine Form von Social Engineering im Anwendersupport. b) Social Engineering ist nur ein Softwareproblem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Phishing ja, menschlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Social Engineering nutzt psychologische Manipulation im Anwendersupport. b) Technische Schutzmaßnahmen reichen zur Abwehr aus.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Manipulation ja, Schulung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Schulungen können Social Engineering im Anwendersupport vorbeugen. b) Social Engineering betrifft nur technische Systeme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schulung ja, menschlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Social Engineering kann Identitätsdiebstahl im Anwendersupport verursachen. b) Firewall schützt vollständig vor Social Engineering.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Identität ja, Firewall unzureichend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Pretexting ist eine Technik von Social Engineering im Anwendersupport. b) Social Engineering ist immer leicht erkennbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pretexting ja, oft subtil"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

